// src/ai-tutor/content/families/subject_kit.js
var shuffle = (a) => {
  const b = [...a];
  for (let i = b.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [b[i], b[j]] = [b[j], b[i]];
  }
  return b;
};
var tbl = (head, rows) => ({ type: "table", data: { head, rows: rows.map((cells) => ({ cells })) } });
var wrongs3 = (w4) => w4.length > 3 ? shuffle(w4).slice(0, 3) : w4;
var hintsOf = (opt) => [opt.h?.[0], opt.h?.[1]].filter(Boolean);
function makeKit({ subject, grade, prefix, map, signed: signed2 }) {
  const { skills: SKILLS15, outcomes: OUTCOMES15, misFeedback: MIS_FEEDBACK15 } = map;
  const feedback = (code, own, why) => {
    if (own) return own;
    const f = MIS_FEEDBACK15[code];
    if (!f) throw new Error(`${subject} family: no misconception ${code}`);
    return why ? `${why} ${f}` : f;
  };
  const choose16 = (cases, opt = {}) => () => {
    const [q, r, w4, why, extra = {}] = pick(cases);
    const wrong = wrongs3(w4).map(([text, mis, own]) => ({ text: String(text), right: false, why: feedback(mis, own, why), mis }));
    const texts = [String(r), ...wrong.map((x) => x.text)];
    if (new Set(texts).size !== texts.length) return null;
    const options = shuffle([{ text: String(r), right: true }, ...wrong]);
    return {
      question: q,
      options,
      instruction: extra.i || opt.instruction || "Choose the best answer.",
      fixedOrder: !!extra.fixed,
      hints: hintsOf(opt),
      steps: [opt.s1 || "Read the question and think about what it is asking.", why],
      ...extra.t ? { model: tbl(extra.t.head, extra.t.rows) } : {}
    };
  };
  const typed12 = (cases, opt = {}) => () => {
    const [q, a, ok5 = [], w4, why, extra = {}] = pick(cases);
    const wrong = wrongs3(w4).map(([text, mis, own]) => [String(text), feedback(mis, own, why), mis]);
    if ((/* @__PURE__ */ new Set([a, ...wrong.map((x) => x[0])])).size !== wrong.length + 1) return null;
    const the = String(a).replace(/^(the|a|an) /i, "");
    return {
      question: q,
      answer: a,
      accepts: [.../* @__PURE__ */ new Set([the, `the ${the}`, ...ok5])],
      wrong,
      instruction: extra.i || opt.instruction || "Type your answer.",
      hints: hintsOf(opt),
      steps: [opt.s1 || "Read the question and think about what it is asking.", why],
      ...extra.t ? { model: tbl(extra.t.head, extra.t.rows) } : {}
    };
  };
  const spot19 = (cases, opt = {}) => () => {
    const [q, steps, fix, mis] = pick(cases);
    feedback(mis);
    return { question: q, working: steps.map(([text, ok5]) => ({ text, ok: ok5 })), fix, mis, hints: hintsOf(opt), steps: [opt.s1 || "Check each step against what you know."], topicDone: true };
  };
  const sfam12 = (d) => {
    const { cs, gen, id: id5, form, rung, oc, ...rest } = d;
    const code = `${prefix}.G${grade}.${cs}`;
    const ck = SKILLS15[code];
    if (!ck) throw new Error(`${id5}: no ${subject} skill ${code}`);
    const outcome = oc ? ck.outcomes.find((o) => o.endsWith(`.${oc}`)) : ck.outcome;
    if (!outcome || !OUTCOMES15[outcome]) throw new Error(`${id5}: outcome ${oc} not on ${cs}`);
    const draw = () => gen();
    return family({ reviewed: signed2.includes(id5), subject, ...rest, id: id5, form, rung, skill: code, cskill: code, outcome, draw, make: (x) => x, check: () => true });
  };
  return { choose: choose16, typed: typed12, spot: spot19, sfam: sfam12, pick, shuffle, tbl };
}

