var WORD3 = "Choose the word that completes the sentence correctly.";
var id3 = (k, s) => `english4.${k}.${s}`;
var L4 = (label, arr) => {
  arr.label = label;
  return arr;
};
var trio3 = (key, cs, pool2, { stem = WORD3, hints, topic, thinOk = false }) => {
  const oc = outcomeLetters(cs, 3);
  return [
    eng({ id: id3(key, "choose"), cs, oc: oc[0], form: "direct", rung: 1, gen: choose5(pool2, { stem, hints }) }),
    eng({ id: id3(key, "gap"), cs, oc: oc[1], form: "direct", rung: 2, thinOk, gen: gap(pool2, { stem: "Type the missing {what} in the sentence.", hints }) }),
    eng({ id: id3(key, "spot"), cs, oc: oc[2], form: "spot", rung: 3, gen: spot5(pool2, { topic, hints }) })
  ];
};
