var ALPHA = [["bat", "bag", "ball", "bad"], ["cap", "can", "cat", "car"], ["dot", "dog", "door", "dove"], ["fan", "farm", "fast", "fat"], ["hand", "happy", "hard", "hat"], ["sand", "save", "sat", "say"], ["map", "mat", "mask", "may"], ["pan", "park", "past", "pat"], ["tap", "tag", "tall", "tab"]];
var GUIDE_WORDS = ["maize", "mango", "map", "market", "mat", "meal", "meat", "melon", "mend", "milk", "mind", "mouse"];
var alphaGen = (cskill) => {
  const words6 = pick(ALPHA), show = shuffle2(words6);
  const right = [...words6].sort().join(", ");
  const firstOnly = show.join(", ");
  const reversed = [...words6].sort().reverse().join(", ");
  const swapped = (() => {
    const w4 = [...words6].sort(), i = randInt(0, 2);
    [w4[i], w4[i + 1]] = [w4[i + 1], w4[i]];
    return w4.join(", ");
  })();
  const fb = feedbackOf(cskill, "M_DIC_ALPHA_FIRST_LETTER");
  const options = mc(right, [[firstOnly, fb, "M_DIC_ALPHA_FIRST_LETTER"], [reversed, fb, "M_DIC_ALPHA_FIRST_LETTER"], [swapped, fb, "M_DIC_ALPHA_FIRST_LETTER"]]);
  if (!options || firstOnly === right) return null;
  return { question: `Which list puts the words ${show.join(", ")} in alphabetical order.`, options, instruction: "Choose the best answer.", hints: ["Look at the first letter of each word. They are the same, so look at the second letter, then the third.", "Compare two words at a time, letter by letter, until they differ."], steps: ["When the first letters match, compare the next letters.", `The alphabetical order is: ${right}.`] };
};
var guideGen = (cskill) => {
  const w4 = [...GUIDE_WORDS].sort();
  const i = randInt(0, w4.length - 5), j = randInt(i + 3, w4.length - 1), g1 = w4[i], g2 = w4[j];
  const test = pick(w4.filter((x) => x !== g1 && x !== g2));
  const inside = g1 < test && test < g2;
  const fb = feedbackOf(cskill, "M_DIC_GUIDE_WORDS");
  return {
    question: `A dictionary page has the guide words "${g1}" and "${g2}". Would the word "${test}" be on this page.`,
    options: mc(inside ? "Yes" : "No", [[inside ? "No" : "Yes", fb, "M_DIC_GUIDE_WORDS"]]),
    instruction: "Choose the best answer.",
    hints: ["The guide words are the first and last words on the page.", "Put the three words in alphabetical order. Is the word in the middle?"],
    steps: [`In alphabetical order: ${[g1, test, g2].sort().join(", ")}.`, inside ? `"${test}" comes between the guide words, so it is on this page.` : `"${test}" does not come between the guide words, so it is not on this page.`],
    chk: () => inside === (g1 < test && test < g2)
  };
};
