var FAMILIES20 = [
  ...trio4("dem", "GRAMMA.T1.DEMONSTRATIVES", DEM, { topic: "using this, these, that and those", hints: ["Count the things. One thing, or more than one?", "Is the thing near the speaker, or far away?"] }),
  ...trio4("coll", "GRAMMA.T2.COLLECTIVE_NOUNS", COLL, { topic: "about groups of animals and things", hints: ["Ask what is in the group: animals, fish, fruit or keys?", "Each kind of animal has its own group word. Say the pair aloud: a ___ of cattle."] }),
  ...trio4("refl", "GRAMMA.T2.REFLEXIVE_PRONOUNS", REFL, { topic: "using myself, yourself, himself, herself, itself, ourselves and themselves", hints: ["Ask who did the action and who received it. Are they the same person?", "The word ends in -self for one person and -selves for more than one."] }),
  ...trio4("too", "GRAMMA.T3.TOO_TO", TOO, { stem: "Choose the words that complete the sentence correctly.", topic: "using too ... to and too ... for", hints: ["After too and an adjective, ask: is a person or a verb next?", "A person after the gap needs for. A verb after the gap needs to."] }),
  ...trio4("must", "GRAMMA.T3.MUST_SHOULD_ADVERB", MUST, { stem: "Choose the words that complete the sentence correctly.", topic: "using must and should", hints: ["After must or should, the verb stays plain: no to, no -s, no -ing.", "The word that tells how an action is done is an adverb and often ends in -ly."] }),
  ...trio4("poss", "GRAMMA.T4.POSSESSIVES", POSS2, { topic: "using words that show who owns something", hints: ["Look at what comes after the gap. Is there a noun, or nothing?", "A possessive word that comes before a noun is not the same as one that stands alone."] }),
  ...trio4("comp", "GRAMMA.T5.COMPARATIVE_SUPERLATIVE", COMP, { stem: "Choose the words that complete the sentence correctly.", topic: "comparing things", hints: ["Count the things being compared. Two things, or three or more?", "Short words take -er and -est. Long words take more and most. Never use both."] }),
  ...trio4("aorder", "GRAMMA.T5.ADJECTIVE_ORDER", ORDER, { stem: "Choose the words that complete the sentence correctly.", topic: "with describing words before a noun", hints: ["In English the describing words come before the noun.", "Size comes first, then age, then shape or colour."] }),
  ...trio4("few", "GRAMMA.T6.FEW_LITTLE", FEW, { topic: "about how much or how many", hints: ["Can you count the thing one by one? Things you can count and things you cannot need different words.", "Does the rest of the sentence say there is enough, or hardly any? Read it carefully."] }),
  ...trio4("quant", "GRAMMA.T6.QUANTIFIERS_OTHER", QUANT, { stem: "Choose the words that complete the sentence correctly.", topic: "using each, all, enough, most and least", hints: ["Each means one at a time. All means many.", "Say the whole sentence aloud and listen for what sounds wrong."] }),
  ...trio4("fut", "GRAMMA.T7.FUTURE_WILL_SHALL", FUT, { topic: "about the future", hints: ["Is the event still to come? Then use will or shall.", "After will or shall, the verb stays plain: no -s, no -ed, no -ing."] }),
  ...trio4("tag", "GRAMMA.T8.QUESTION_TAGS", TAG, { stem: "Choose the tag that completes the sentence correctly.", topic: "with question tags at the end", hints: ["Find the helper verb in the statement (is, are, does, can, have).", "The tag turns the sign round and uses a pronoun: a positive statement gets a negative tag, and a negative statement gets a positive tag."] }),
  ...trio4("adv", "GRAMMA.T9.ADVERBS", ADV2, { topic: "using adverbs", hints: ["Ask: does the word tell how, when, where or how often?", "A word that describes a verb is an adverb. Many end in -ly, but not all of them do."] }),
  eng2({ id: "eng5.advkind.choose", kind: "classify", cs: "GRAMMA.T9.ADVERBS", oc: "a", form: "direct", rung: 1, gen: choose6(ADV_KIND2, { stem: "Complete the sentence.", hints: ["Ask: does the word say how, when, where or how often?", "How often: always, never, often, sometimes. When: today, soon, later. Where: here, there, outside."] }) }),
  ...trio4("could", "GRAMMA.T9.COULD_WOULD", COULD, { topic: "using could and would", hints: ["Is the sentence about the past, or about an imagined result?", "After the helper verb, the main verb stays plain."] }),
  ...trio4("conj", "GRAMMA.T10.CONJUNCTIONS", CONJ, { topic: "joining ideas", hints: ["Say the two parts. Is the second a reason, a surprise, an addition or a choice?", "Each kind of link needs its own joining word: one for a reason, one for a surprise, one for a choice."] }),
  eng2({ id: "eng5.conjs.choose", kind: "choose-sentence", cs: "GRAMMA.T10.CONJUNCTIONS", oc: "c", form: "direct", rung: 2, gen: choose6(CONJ_SENT, { stem: SENT3, hints: ["Check the meaning of the two parts, then the joining word.", "Use only one joining word between two ideas."] }) }),
  ...trio4("int", "GRAMMA.T11.INTERROGATIVES", INTER, { stem: "Choose the words that complete the question correctly.", topic: "asking questions", hints: ["Look at the answer given. Does it name a person, a time, a reason or a thing?", "In a question the helper verb comes before the subject."] }),
  ...trio4("same", "GRAMMA.T12.SAME_SINGULAR_PLURAL", SAME, { topic: "about animals and people", hints: ["A few nouns do not change in the plural, and some change inside the word.", "Look for a number or the word many: it shows whether there is one or more than one."] }),
  ...trio4("ptime", "GRAMMA.T13.PREPOSITIONS_TIME_PLACE", TIME, { thinOk: true, topic: "about time and place", hints: ["At is for a clock time or a point. On is for days and for a surface. In is for months, parts of the day and inside.", "Say the whole sentence aloud and listen for what sounds right."] }),
  ...trio4("pdir", "GRAMMA.T13.PREPOSITIONS_DIRECTION", DIR, { topic: "about going to places", hints: ["Some words already carry the idea of going to a place.", "Does the movement go in at one side and out at the other, or does it stay inside?"] }),
  ...duo3("comma", "WRITIN.T7.COMMAS", COMMA, { topic: "with commas", hints: ["Look for a list or an opening word: commas go there.", "A comma is not a breath mark: never split who from what they did."] }),
  ...duo3("speech", "WRITIN.T7.DIRECT_SPEECH", SPEECH, { topic: "with someone speaking", hints: ["Double quotation marks go round the spoken words only.", "The comma or question mark that ends the speech goes inside the closing marks, and the speech starts with a capital."] }),
  ...trio4("apos", "WRITIN.T9.APOSTROPHE", APOS, { stem: "Choose the word that completes the sentence correctly.", topic: "with apostrophes", hints: ["An apostrophe shows that something belongs to someone, or that a letter is missing.", "A plain plural has no apostrophe, and the word that means belonging to it has none either."] }),
  ...duo3("excl", "WRITIN.T9.EXCLAMATION_MARK", EXCL, { topic: "with the exclamation mark", hints: ["Is it a shout, a warning or a cry of surprise? Then one exclamation mark.", "Calm statements end with a full stop and questions end with a question mark."] }),
  ...trio4("homo", "WRITIN.T11.HOMOPHONES", HOMO, { topic: "with words that sound the same", hints: ["The words sound the same, so think about the meaning of the sentence.", "Say what the word means in your own words, then match it to the spelling."] }),
  ...trio4("dbl", "WRITIN.T13.DOUBLE_LETTERS", DOUBLE, { stem: "Choose the correct spelling to complete the sentence.", topic: "with words that have double letters", hints: ["Say the word slowly in parts and listen for a sound that needs two letters.", "Think of other words you know that have double letters."] })
];

// src/ai-tutor/content/families/eng_g5_vocab.js
var WORD5 = "Choose the word that completes the sentence correctly.";
var L5 = (label, arr) => {
  arr.label = label;
  return arr;
};
var trio5 = (key, cs, pool2, { stem = WORD5, hints, topic, oc = outcomeLetters2(cs, 3) }) => [
  eng2({ id: `eng5.${key}.choose`, cs, oc: oc[0], form: "direct", rung: 1, gen: choose6(pool2, { stem, hints }) }),
  eng2({ id: `eng5.${key}.gap`, cs, oc: oc[1], form: "direct", rung: 2, gen: gap2(pool2, { stem: "Type the missing {what} in the sentence.", hints }) }),
  eng2({ id: `eng5.${key}.spot`, cs, oc: oc[2], form: "spot", rung: 3, gen: spot6(pool2, { topic, hints }) })
];
