var gap3 = (pool2, { stem, hints }) => (cskill) => {
  const list = items3(cskill, pool2.filter((it2) => blankOf3(it2[0]))), it = pick(list);
  const many = /\s/.test(it.right);
  return {
    question: `${stem.replace("{what}", many ? "words" : "word")} "${it.text}"`,
    answer: it.right,
    accepts: it.alt,
    wrong: it.wrongs.map(([w4, code, why]) => [w4, why, code]),
    instruction: "Type your answer.",
    hints: [...hints, `The first letter is "${it.right[0]}".`],
    steps: [it.because, `The answer is "${it.right}".`],
    chk: (a) => [it.right, ...it.alt].includes(String(a))
  };
};
