    c("Which method separates the dyes in black ink?", "Chromatography", "The dyes travel different distances on paper.", ["M_SE_CHROMA_COLOUR", "Boiling the ink", "Sieving the ink"], ["M_SE_FILTER_SALT", "Filtering the ink"]),
    c("What does filtering NOT separate?", "A dissolved solid from its liquid", "A dissolved solid passes through the filter.", ["M_SE_FILTER_SALT", "Sand from water", "Soil from water"], ["M_SE_EVAP_DISTIL", "Small stones from a heap of flour"]),
    c("Which method separates two liquids with different boiling points?", "Fractional distillation", "Fractional distillation uses different boiling points.", ["M_SE_EVAP_DISTIL", "Filtering", "Evaporation"], ["M_SE_CHROMA_COLOUR", "Chromatography"])
