    c2("Aisha looks at a friend through a clear plastic bag and sees her clearly. What is the bag?", "Transparent", "She can see clearly.", ["M_LM_TRANSLUCENT_TRANSPARENT", "Translucent", "Opaque"], ["M_LM_COLOUR_OPAQUE", "Opaque because it is plastic"]),
    c2("A bathroom window lets in light but nobody can see through it clearly. What is the glass?", "Translucent", "It lets some light through only.", ["M_LM_TRANSLUCENT_TRANSPARENT", "Transparent", "Opaque"], ["M_LM_GLASS_ALWAYS", "Opaque"]),
    c2("Ken says all glass is transparent. Which glass shows he is wrong?", "Frosted bathroom glass", "Frosted glass is translucent.", ["M_LM_GLASS_ALWAYS", "A clear window", "A clear bottle"], ["M_LM_TRANSLUCENT_TRANSPARENT", "Clear water"]),
    c2("Njeri says coloured cellophane is opaque because it is coloured. What can you tell her?", "It lets light through, so it is not opaque", "Colour does not decide.", ["M_LM_COLOUR_OPAQUE", "She is right", "It is transparent only if it is not coloured"], ["M_LM_TRANSLUCENT_TRANSPARENT", "It must be transparent"]),
    c2("A thick wall casts no light to the other side. What kind of material is it?", "Opaque", "It blocks all light.", ["M_LM_COLOUR_OPAQUE", "Translucent", "Transparent"], ["M_LM_GLASS_ALWAYS", "Glass"])
