    c2("The reflected ray makes 55 degrees with the normal. What was the angle of incidence?", "55 degrees", "The two angles are equal.", ["M_MR_NOT_EQUAL", "35 degrees", "110 degrees"], ["M_MR_FROM_SURFACE", "125 degrees"]),
    c2("Why is a dotted normal line drawn in a ray diagram?", "To measure the angles from it", "The angles are measured from the normal.", ["M_MR_FROM_SURFACE", "To show the mirror surface", "To show the ray path"], ["M_MR_NOT_EQUAL", "To make the angles different"])
