// src/ai-tutor/content/subjects/registry.js
var REQUIRED = ["subject", "grade", "prefix", "name", "shortName", "icon", "description", "map", "families", "familyFiles", "signed", "signedFile", "checks"];
for (const e of ENTRIES) {
  for (const k of REQUIRED) if (e[k] === void 0) throw new Error(`subject entry ${e.subject}_g${e.grade}: missing ${k}`);
  for (const k of ["skills", "substrands", "outcomes", "misFeedback"]) if (!e.map[k]) throw new Error(`subject entry ${e.subject}_g${e.grade}: map.${k} missing`);
  if (!["family", "text"].includes(e.checks)) throw new Error(`subject entry ${e.subject}_g${e.grade}: checks must be 'family' or 'text'`);
}
var orderOf = (e) => e.order ?? 100;
var SUBJECT_ORDER = [...new Set(ENTRIES.map((e) => e.subject))].sort((a, b) => orderOf(ENTRIES.find((e) => e.subject === a)) - orderOf(ENTRIES.find((e) => e.subject === b)) || a.localeCompare(b));
var entriesOf4 = (subject) => ENTRIES.filter((e) => e.subject === subject).sort((a, b) => a.grade - b.grade);
var bankFamilies = () => ENTRIES.filter((e) => e.bank).flatMap((e) => e.families);
var familiesOutsideBank = () => ENTRIES.filter((e) => !e.bank).flatMap((e) => e.families);
function subjectDef(subject) {
  const es = entriesOf4(subject);
  if (!es.length) return void 0;
  const first = es[0];
  const join = (k) => Object.assign({}, ...es.map((e) => e.map[k]));
  return {
    id: subject,
    name: first.name,
    shortName: first.shortName,
    icon: first.icon,
    description: es.length === 1 ? first.description : `${first.name} for Grades ${es.map((e) => e.grade).join(", ")} from the CBC design`,
    map: join("skills"),
    substrands: join("substrands"),
    outcomes: join("outcomes"),
    families: () => es.flatMap((e) => e.families)
  };
}
var SUBJECT_DEFS_LIST = SUBJECT_ORDER.map(subjectDef);
var skillMapOf = (subject) => subjectDef(subject)?.map || {};
var substrandsOf = (subject) => subjectDef(subject)?.substrands || {};

