var fam12 = (def) => family({ reviewed: false, ...def });
var rot = (arr, k) => {
  const n = k % arr.length;
  return [...arr.slice(n), ...arr.slice(0, n)];
};
var uniq = (...v) => new Set(v.map(String)).size === v.length;
var r10 = (n) => Math.round(n / 10) * 10;
var f10 = (n) => Math.floor(n / 10) * 10;
var sum = (a) => a.reduce((x, y) => x + y, 0);
var cap = (s) => s.charAt(0).toUpperCase() + s.slice(1);
var ONES = ["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"];
var TENS = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"];
var w99 = (n) => n < 20 ? ONES[n] : TENS[Math.floor(n / 10)] + (n % 10 ? `-${ONES[n % 10]}` : "");
var words = (n) => {
  const t = Math.floor(n / 1e3), h = Math.floor(n % 1e3 / 100), u = n % 100, s = [];
  if (t) s.push(`${ONES[t]} thousand`);
  if (h) s.push(`${ONES[h]} hundred`);
  if (u) s.push(t || h ? `and ${w99(u)}` : w99(u));
  return s.join(" ");
};
var ROMAN = { 2: "II", 3: "III", 4: "IV", 7: "VII", 8: "VIII", 9: "IX" };
