      x.question = `Practising "${ck.name.charAt(0).toLowerCase()}${ck.name.slice(1).replace(/ \((proposed[^)]*)\)/, "")}": ${q.charAt(0).toLowerCase() === q.charAt(0) ? q : q.charAt(0) + q.slice(1)}`;
