var EVENTS = [["get up for school", 6, "a.m."], ["start school assembly", 8, "a.m."], ["eat lunch", 1, "p.m."], ["go home after games", 4, "p.m."], ["eat supper", 7, "p.m."], ["go to bed", 9, "p.m."]];
