      const options = mc5(right, [[swapped, "The short hand shows the hour and the long hand shows the minutes. You swapped them.", "M_TIME_HANDS_SWAPPED"], [mirror, "Check which side of the clock the long hand is on: past the hour is the right side.", "M_TIME_PAST_TO_SWAP"], [next, "The short hand is just past " + h + ", so the hour is still " + h + ".", "M_TIME_HANDS_SWAPPED"]]);
