      const options = mc5(HM(h, m4), [[HM(h - 1, m4 + 60), "Take out as many whole hours as you can. 60 minutes make one hour.", "M_TIME_REMAINDER_AS_DECIMAL"], [HM(Math.floor(Tm / 100), Tm % 100), "There are 60 minutes in an hour, not 100.", "M_TIME_100_MINUTES"], [HM(m4, h), "The hours come first, then the minutes.", "M_TIME_100_MINUTES"]].filter((w4) => !/^0/.test(w4[0])));
