      const options = mc5(HM(dh, dm), [[HM(b - a, m1 - m22), "You took the smaller number of minutes from the larger. Count up to the next hour first.", "M_TIME_SUBTRACT_AS_DECIMAL"], [HM(dh, 100 + m22 - m1), "An hour has 60 minutes, not 100.", "M_TIME_SUBTRACT_AS_DECIMAL"], [HM(b - a, m22), "Count the minutes from the start time to the next hour as well.", "M_TIME_SUBTRACT_AS_DECIMAL"]]);
