      const options = mc5(right, [[wrong1, quarterTo ? "Quarter to is before the hour: it is 45 minutes past the hour before." : "45 minutes past is a quarter to the next hour. Quarter past is 15 minutes.", "M_TIME_DIGITAL_ANALOGUE_SWAP"], [wrong2, "Check the hour and the minutes again.", "M_TIME_DIGITAL_ANALOGUE_SWAP"], [wrong3, "Check the hour and the minutes again.", "M_TIME_DIGITAL_ANALOGUE_SWAP"]]);
