          { text: `Area of one triangle = ${T11(tri)} cm\xB2`, ok: tri === round(f * s * a, 2) },
          { text: `Area of the pentagon = ${n} \xD7 ${T11(tri)} = ${T11(total)} cm\xB2`, ok: total === round(n * tri, 2) }
