// src/school/statesDoor.js
var STATES_MAX_LEARNERS = 300;
var STATES_REASON_MAX_LEARNERS = 5;
var REF7 = /^[A-Z2-9]{8}$/;
var ok4 = (body) => ({ status: 200, body: { success: true, ...body } });
var no4 = (status, error) => ({ status, body: { success: false, error } });
function statesFor(rows, { now, withReason = false } = {}) {
  const m4 = learnerMastery(rows, { now });
  const skills = m4.skills.map((s) => ({
    code: s.key,
    state: s.state,
    word: s.word,
    due: !!s.dueRecheck,
    marks: s.marks,
    ...withReason ? { reason: s.reason } : {}
  }));
  const outcomes = m4.outcomes.map((o) => ({
    code: o.code,
    state: o.state,
    word: o.word,
    due: o.word === MASTERED_DUE_WORDS,
    skills: o.skillKeys.length,
    ...withReason ? { reason: o.reason } : {}
  }));
  return { skills, outcomes };
}
async function doorLearnerStates(door, p, deps) {
  if (p.action !== "learner_states") return null;
  const refs = [...new Set((Array.isArray(p.learner_refs) ? p.learner_refs : []).map(String).filter((r) => REF7.test(r)))];
  if (!refs.length) return no4(400, "No learners given");
  if (refs.length > STATES_MAX_LEARNERS) return no4(413, `${STATES_MAX_LEARNERS} learners at most in one call`);
  const byLearner = await deps.store.learnerEvidence(door.id, refs);
  const now = deps.now ? deps.now() : Date.now();
  const withReason = refs.length <= STATES_REASON_MAX_LEARNERS;
  const states = {};
  for (const ref of refs) {
    const rows = byLearner[ref];
    if (rows && rows.length) states[ref] = statesFor(rows, { now, withReason });
  }
  return ok4({ learners: refs.length, with_evidence: Object.keys(states).length, states });
}

// src/school/homeworkStore.js
var SITTING_COLS = [
  "id",
  "homework_id",
  "learner_ref",
  "code",
  "seed",
  "version",
  "items",
  "answers",
  "status",
  "started_at",
  "finished_at",
  "locked_at",
  "lock_reason",
  "lock_question",
  "reopen_count",
  "pushed_at"
];
var pickCols = (s) => Object.fromEntries(SITTING_COLS.filter((k) => s[k] !== void 0).map((k) => [k, s[k]]));
function supabaseStore(admin) {
  return {
    async getHomework(doorId, ref) {
      const { data } = await admin.from("school_homework").select("*").eq("door_id", doorId).eq("homework_ref", ref).maybeSingle();
      return data || null;
    },
    async saveHomework(row) {
      const { data, error } = await admin.from("school_homework").insert(row).select("*").single();
      if (error) throw new Error("Not saved");
      return data;
    },
    async sittingsOf(homeworkId) {
      const { data } = await admin.from("school_homework_sittings").select("*").eq("homework_id", homeworkId).order("learner_ref").limit(2e3);
      return data || [];
    },
    async saveSittings(rows) {
      for (let i = 0; i < rows.length; i += 100) {
        const { error } = await admin.from("school_homework_sittings").insert(rows.slice(i, i + 100).map(pickCols));
        if (error) throw new Error("Not saved");
      }
    },
    async sittingByCode(code) {
      const { data } = await admin.from("school_homework_sittings").select("*, school_homework(*, school_doors(id, code, secret, active, results_url))").eq("code", code).maybeSingle();
      if (!data || !data.school_homework?.school_doors?.active) return null;
      const { school_homework: hw, ...sitting } = data;
      const { school_doors: door, ...homework } = hw;
      return { sitting, homework, door };
    },
    async saveSitting(s) {
      const { id: id5, ...rest } = pickCols(s);
      await admin.from("school_homework_sittings").update({ ...rest, updated_at: (/* @__PURE__ */ new Date()).toISOString() }).eq("id", id5);
    },
    // One evidence row for the learner's log (response_events, migration 20261111_learner_evidence.sql). A duplicate
    // (the unique index on source, item_ref and learner) is the row already being there, which is what the log wants.
    async saveEvidence(row) {
      const { error } = await admin.from("response_events").insert(row);
      if (error && error.code !== "23505") throw new Error("Not saved");
    },
    // School exam evidence (evidenceDoor.js): what is already in the log for these items, new rows in batches, a corrected mark in place.
    async examEvidence(doorId, itemRefs) {
      const out = [];
      for (let i = 0; i < itemRefs.length; i += 100) {
        const { data, error } = await admin.from("response_events").select("id, item_ref, learner_ref, marks, max_marks, outcome_code, substrand_code").eq("source", "school_exam").eq("door_id", doorId).in("item_ref", itemRefs.slice(i, i + 100)).limit(2e4);
        if (error) throw new Error("Not read");
        out.push(...data || []);
      }
      return out;
    },
    // Everything the log holds for these school learners, by reference (class_rechecks, recheckDoor.js): school rows by
    // door and reference, practice rows where the learner is linked to a HOREB child. Evidence columns only.
    async learnerEvidence(doorId, refs) {
      const COLS = "source, skill_id, cskill, outcome_code, substrand_code, correct, marks, max_marks, independent, hints_used, difficulty, item_ref, client_ts, created_at";
      const out = {};
      for (let i = 0; i < refs.length; i += 50) {
        const part = refs.slice(i, i + 50);
        const { data, error } = await admin.from("response_events").select(`learner_ref, ${COLS}`).eq("door_id", doorId).in("learner_ref", part).limit(2e4);
        if (error) throw new Error("Not read");
        for (const r of data || []) {
          const { learner_ref, ...row } = r;
          (out[learner_ref] ||= []).push(row);
        }
        const { data: links, error: le } = await admin.from("school_learner_links").select("learner_ref, parent_id, child_id").eq("door_id", doorId).in("learner_ref", part);
        if (le) throw new Error("Not read");
        const byPair = new Map((links || []).map((l) => [`${l.parent_id}|${l.child_id}`, l.learner_ref]));
        const parents = [...new Set((links || []).map((l) => l.parent_id))], kids = [...new Set((links || []).map((l) => l.child_id))];
        if (parents.length) {
          const { data: rows, error: pe } = await admin.from("response_events").select(`student_id, learner_id, ${COLS}`).in("student_id", parents).in("learner_id", kids).eq("source", "practice").limit(2e4);
          if (pe) throw new Error("Not read");
          for (const r of rows || []) {
            const ref = byPair.get(`${r.student_id}|${r.learner_id}`);
            if (!ref) continue;
            const { student_id, learner_id, ...row } = r;
            (out[ref] ||= []).push(row);
          }
        }
      }
      return out;
    },
    async insertEvidence(rows) {
      for (let i = 0; i < rows.length; i += 200) {
        const { error } = await admin.from("response_events").insert(rows.slice(i, i + 200));
        if (error && error.code === "23505") {
          for (const r of rows.slice(i, i + 200)) {
            const e = (await admin.from("response_events").insert(r)).error;
            if (e && e.code !== "23505") throw new Error("Not saved");
          }
        } else if (error) throw new Error("Not saved");
      }
    },
    async updateEvidence(id5, patch) {
      const { error } = await admin.from("response_events").update(patch).eq("id", id5).eq("source", "school_exam");
      if (error) throw new Error("Not saved");
    },
    // The learner home (learnerHome.js, migration 20261111_learner_home.sql).
    async homeDoor(code) {
      const { data } = await admin.from("school_doors").select("id, code, name, secret, active").eq("code", code).maybeSingle();
      return data && data.active ? data : null;
    },
    async homeSittings(doorId, ref) {
      const { data } = await admin.from("school_homework_sittings").select("code, status, items, answers, started_at, finished_at, locked_at, lock_question, school_homework!inner(door_id, title, mode, due_on, created_at)").eq("learner_ref", ref).eq("school_homework.door_id", doorId).order("updated_at", { ascending: false }).limit(60);
      return (data || []).map(({ school_homework: homework, ...sitting }) => ({ sitting, homework }));
    },
    async homeTries(key, sinceIso) {
      const { count } = await admin.from("school_home_attempts").select("id", { count: "exact", head: true }).eq("try_key", key).eq("ok", false).gte("at", sinceIso);
      return count || 0;
    },
    async homeTry(key, ok5) {
      await admin.from("school_home_attempts").insert({ try_key: key, ok: ok5 });
      await admin.from("school_home_attempts").delete().eq("try_key", key).lt("at", new Date(Date.now() - 864e5).toISOString());
    },
    async childLink(userId, childId) {
      const { data } = await admin.from("school_learner_links").select("learner_ref, linked_at, school_doors(id, code, name, active)").eq("parent_id", userId).eq("child_id", childId).order("linked_at", { ascending: false }).limit(5);
      const l = (data || []).find((x) => x.school_doors?.active);
      return l ? { door: { id: l.school_doors.id, code: l.school_doors.code, name: l.school_doors.name }, learner_ref: l.learner_ref } : null;
    }
  };
}

// scripts/school-practice.template.ts
var HOREB_SITE = "https://tutagora.com";
var env = (k) => Deno.env.get(k) || "";
var json = (status, body) => new Response(JSON.stringify(body), { status, headers: { "content-type": "application/json" } });
Deno.serve(async (req) => {
  if (req.method !== "POST") return json(405, { success: false, error: "POST only" });
  const body = await req.text();
  if (body.length > 2e5) return json(413, { success: false, error: "Too large" });
  const code = (req.headers.get("x-door-code") || "").toUpperCase();
  if (!/^[A-Z]{2,6}$/.test(code)) return json(401, { success: false, error: "Unknown school" });
  const admin = createClient(env("SUPABASE_URL"), env("SUPABASE_SERVICE_ROLE_KEY"));
  const { data: door } = await admin.from("school_doors").select("id, code, secret, active").eq("code", code).maybeSingle();
  if (!door || !door.active) return json(401, { success: false, error: "Not allowed" });
  const v = await verifyCall(door.secret, req.headers.get("x-door-time"), body, req.headers.get("x-door-sign"), Math.floor(Date.now() / 1e3));
  if (!v.ok) return json(401, { success: false, error: "Not allowed" });
  let p;
  try {
    p = JSON.parse(body);
  } catch {
    return json(400, { success: false, error: "Not JSON" });
  }
  if (p.action === "assign") {
    const c3 = cleanAssign(p);
    if (!c3.ok) return json(400, { success: false, error: c3.error });
    const { error } = await admin.from("school_practice").upsert(
      { door_id: door.id, ...c3.row, updated_at: (/* @__PURE__ */ new Date()).toISOString() },
      { onConflict: "door_id,practice_ref" }
    );
    if (error) return json(500, { success: false, error: "Not saved" });
    return json(200, { success: true, skills: c3.row.skill_ids.length, learners: c3.row.learner_refs.length });
  }
  if (p.action === "status") {
    const refs = (Array.isArray(p.practice_refs) ? p.practice_refs : []).map(String).filter((r) => /^[a-f0-9-]{36}$/.test(r)).slice(0, 100);
    if (!refs.length) return json(200, { success: true, status: {} });
    const { data: practices } = await admin.from("school_practice").select("practice_ref, skill_ids, learner_refs").eq("door_id", door.id).in("practice_ref", refs);
    const allRefs = [...new Set((practices || []).flatMap((x) => x.learner_refs || []))];
    const { data: links } = allRefs.length ? await admin.from("school_learner_links").select("learner_ref, parent_id, child_id").eq("door_id", door.id).in("learner_ref", allRefs) : { data: [] };
    const keys = (links || []).map((l) => childProfileKey(l.parent_id, l.child_id));
    const progress = {};
    if (keys.length) {
      const { data: rows } = await admin.from("ai_tutor_progress").select("profile_key, progress").in("profile_key", keys);
      for (const r of rows || []) progress[r.profile_key] = r.progress || {};
    }
    return json(200, { success: true, status: practiceStatus(practices || [], links || [], progress) });
  }
  if (p.action === "evidence") {
    const r = await doorEvidence(door, p, { store: supabaseStore(admin) }).catch(() => ({ status: 500, body: { success: false, error: "Not saved" } }));
    return json(r.status, r.body);
  }
  if (p.action === "class_rechecks") {
    const r = await doorClassRechecks(door, p, { store: supabaseStore(admin), now: () => Date.now() }).catch(() => ({ status: 500, body: { success: false, error: "Not read" } }));
    return json(r.status, r.body);
  }
  if (p.action === "learner_states") {
    const r = await doorLearnerStates(door, p, { store: supabaseStore(admin), now: () => Date.now() }).catch(() => ({ status: 500, body: { success: false, error: "Not read" } }));
    return json(r.status, r.body);
  }
  if (String(p.action || "").startsWith("homework_")) {
    const r = await doorHomework(door, p, {
      store: supabaseStore(admin),
      now: () => Date.now(),
      makeCode: makeCodeFrom((n) => crypto.getRandomValues(new Uint8Array(n))),
      linkFor: (c3) => `${HOREB_SITE}/hw/?c=${c3}`
    }).catch(() => ({ status: 500, body: { success: false, error: "Not saved" } }));
    if (r) return json(r.status, r.body);
  }
  return json(400, { success: false, error: "Unknown action" });
});
